solution:
%dw 2.0
output application/json
import * from dw::Runtime
---
do {
  var results = payload map (d) -> { id: d.id, t: try(() -> read(d.body, "application/json")) }
  ---
  {
    parsed: (results filter $.t.success) map { id: $.id, data: $.t.result },
    rejected: (results filter not $.t.success).id default []
  }
}

