%dw 2.0
output application/json
---
do {
  var results = payload map (d) -> { id: d.id, data: read(d.body, "application/json") default null }
  ---
  {
    parsed: (results filter $.data != null) map { id: $.id, data: $.data },
    rejected: (results filter $.data == null).id default []
  }
}

